// Extraer variables enviadas desde el Chatbot de CanisCalm
const body = $json.body || $json;
const userMessage = body.message || '¿Cómo reduzco la reactividad?';
const dogName = body.dog_name || 'mi perro';
const breed = body.breed || 'raza canina';

const systemPrompt = `Eres Kira AI, una educadora canina experta en modificación de conducta y gestión de reactividad en paseos.\nEstás ayudando a la familia de ${dogName}, un perro de raza ${breed}.\nTu objetivo es dar respuestas claras, empáticas, prácticas y estructuradas en viñetas.\nPromueve siempre la desensibilización sistemática, el método LAT (Look At That), la regla de los 3 segundos, distancias de confort y refuerzo positivo sin aversivos.\nMantén tus respuestas concisas (máximo 150 palabras).`;

return [{
  json: {
    systemPrompt,
    userMessage,
    dogName,
    breed
  }
}];

// Extraer el texto generado por la API del Modelo de IA
const response = $json;
let reply = 'No se recibió respuesta del modelo de IA.';

if (response.choices && response.choices.length > 0 && response.choices[0].message) {
  reply = response.choices[0].message.content;
} else if (response.reply || response.output || response.text) {
  reply = response.reply || response.output || response.text;
}

return [{ json: { reply } }];
